public string SelectLookup(string lookupValue) {
   string connectionString = @"Server=DESKTOP-H7BVMV9\SQLEXPRESS;Database=EDI;Integrated Security=true;TrustServerCertificate=true;";

   try {
        using (var conn = new Microsoft.Data.SqlClient.SqlConnection(connectionString))
        using (var cmd = new Microsoft.Data.SqlClient.SqlCommand("Select PartnerCode,PartnerName,ISA06,AddressLine1,AddressLine2,City,StateProvince,PostalCode,CountryCode from Partner where PartnerCode=@Param", conn)) {    
            cmd.Parameters.Add(new Microsoft.Data.SqlClient.SqlParameter("@Param", lookupValue));

            // Fully qualify SqlDataAdapter under Microsoft.Data.SqlClient
            using (var adapter = new Microsoft.Data.SqlClient.SqlDataAdapter(cmd)) {
                 var dt = new DataTable("Rows");

                 adapter.Fill(dt);

                 // Serialize the DataTable to an XML string so XSLT can iterate over the rows
                 using (var sw = new System.IO.StringWriter()) {
                     dt.WriteXml(sw, XmlWriteMode.IgnoreSchema);
                     return sw.ToString();
                 }
             }
         }
    }
    catch (Exception ex) {
        // Gracefully return error message or empty string on failure
        return ex.Message;
    }
}
